import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Exact original source/runtime binding and owned Linux process-group execution. */
final class LeafCutterWorkflowRuntime {
    private LeafCutterWorkflowRuntime() { }
    static final class Unavailable extends IOException {
        private static final long serialVersionUID=1L;
        Unavailable(String message,Throwable cause){super(message,cause);}
    }
    static byte[] resource(String name)throws IOException {
        NextflowFiles.member(name);try(var stream=LeafCutterWorkflowRuntime.class.getResourceAsStream("/org/jlinalg/omics/leafcutter-workflow/"+name)){require(stream!=null,"Missing packaged original LeafCutter source/setup member: "+name);byte[] raw=stream.readNBytes(33554433);require(raw.length<=33554432,"Packaged source member capacity exceeded");return raw;}
    }
    static Map<String,Object> read(Path path,int maximum)throws IOException{return object(NextflowParameters.parse(NextflowFiles.utf8(NextflowFiles.bytes(path,maximum)),maximum,4000000));}
    static Map<String,Object> profile()throws IOException{return object(NextflowParameters.parse(NextflowFiles.utf8(resource("profiles.json")),4194304,1000000));}
    static Map<String,Object> workerProfile()throws IOException{return object(NextflowParameters.parse(NextflowFiles.utf8(resource("worker-profile.json")),4194304,1000000));}
    static Map<String,Object> pinObject(NextflowFiles.Pin pin){return Map.of("bytes",pin.bytes(),"sha256",pin.sha256());}
    record Prepared(Path manifestPath,byte[] original,NextflowFiles.Pin manifestPin,Path prefix,Path library,
                    Path inventory,NextflowFiles.Pin inventoryPin,Path libraryInventory,NextflowFiles.Pin libraryPin) {
        Path python(){return prefix.resolve("bin/python");}
        void verify()throws IOException{
            require(manifestPin.equals(NextflowFiles.pin(manifestPath,67108864,()->{}))&&inventoryPin.equals(NextflowFiles.pin(inventory,67108864,()->{}))&&libraryPin.equals(NextflowFiles.pin(libraryInventory,67108864,()->{})),"Original runtime binding/inventory changed");
            HailWorkflowRuntime.verifyTree(prefix,read(inventory,67108864));HailWorkflowRuntime.verifyTree(library,read(libraryInventory,67108864));require(Files.isExecutable(python())&&Files.isExecutable(prefix.resolve("bin/Rscript")),"Required exact original Python/R executable permission unavailable");
        }
    }
    static Prepared prepare(LeafCutterWorkflowRequest.Request r)throws IOException {
        try{
            require(System.getProperty("os.name").equals("Linux")&&Set.of("amd64","x86_64").contains(System.getProperty("os.arch")),"Original LeafCutter execution requires Linux x86_64. Run this Java CLI inside Linux/WSL with the named exact runtime. Native Java clustering, phenotype and model-evaluation APIs remain portable");var profile=profile();require(r.edition().equals(text(profile.get("edition"))),"Requested exact LeafCutter source edition is not supported by this runtime profile; no release/version fallback occurs");byte[] raw=NextflowFiles.bytes(r.runtime(),67108864);var m=read(r.runtime(),67108864);var manifestPin=new NextflowFiles.Pin(raw.length,NextflowFiles.sha(raw));require(manifestPin.equals(NextflowFiles.pin(r.runtime(),67108864,()->{})),"Runtime manifest changed during capture");require(text(m.get("status")).equals("PASS_BOUND_ORIGINAL_LEAFCUTTER_WORKFLOW_RUNTIME_ONLY")&&Boolean.TRUE.equals(m.get("runtime_trees_unchanged"))&&Boolean.FALSE.equals(m.get("namespace_patched")),"Require a complete unchanged original LeafCutter runtime binding; setup health alone is not analysis admission");require(text(m.get("edition")).equals(r.edition())&&text(m.get("revision")).equals(text(profile.get("revision")))&&text(m.get("R_package_version")).equals(text(profile.get("R_package_version"))),"Exact original source revision/R package version differs");var profilePin=NextflowFiles.fingerprint(m.get("profile"),4194304);require(profilePin.equals(new NextflowFiles.Pin(resource("profiles.json").length,NextflowFiles.sha(resource("profiles.json")))),"Runtime was prepared against a different exact source/setup profile; preserve it and prepare a NEW matching binding");var health=object(m.get("health"));require(text(health.get("status")).equals("PASS_ORIGINAL_LEAFCUTTER_NAMESPACE_AND_LOSSLESS_EXPORT_ONLY")&&text(health.get("version")).equals("0.2.9")&&text(health.get("rstan")).equals("2.21.8")&&text(health.get("jsonlite")).equals("1.8.8")&&list(health.get("namespace_functions_checked")).size()==24&&Boolean.TRUE.equals(health.get("lossless_roundtrip")),"Original namespace/precision health differs");Path prefix=NextflowFiles.directory(Path.of(text(m.get("runtime_environment")))),library=NextflowFiles.directory(Path.of(text(m.get("R_library"))));require(Path.of(text(m.get("runtime_python"))).equals(prefix.resolve("bin/python"))&&Path.of(text(m.get("Rscript"))).equals(prefix.resolve("bin/Rscript")),"Unexpected original executable binding");var result=new Prepared(r.runtime(),raw,manifestPin,prefix,library,r.runtime().getParent().resolve("runtime-before.json"),NextflowFiles.fingerprint(m.get("runtime_inventory"),67108864),r.runtime().getParent().resolve("library-before.json"),NextflowFiles.fingerprint(m.get("library_inventory"),67108864));result.verify();return result;
        }catch(IOException|RuntimeException failure){throw new Unavailable("Exact permitted LeafCutter runtime unavailable; dependent batch skipped. "+failure,failure);}
    }
    static void sources(Path destination)throws IOException {
        Files.createDirectory(destination);var files=new LinkedHashMap<String,Object>(object(profile().get("files")));files.putAll(object(workerProfile().get("files")));for(var entry:files.entrySet()){String name=NextflowFiles.member(entry.getKey());byte[] raw=resource(name);var want=NextflowFiles.fingerprint(entry.getValue(),33554432);require(want.equals(new NextflowFiles.Pin(raw.length,NextflowFiles.sha(raw))),"Packaged original/worker source identity differs: "+name);Path file=destination.resolve(name);Files.createDirectories(file.getParent());Files.write(file,raw,StandardOpenOption.CREATE_NEW);}for(String name:List.of("profiles.json","worker-profile.json"))Files.write(destination.resolve(name),resource(name),StandardOpenOption.CREATE_NEW);
    }
    static void verifySources(Path destination)throws IOException {
        var files=new LinkedHashMap<String,Object>(object(profile().get("files")));files.putAll(object(workerProfile().get("files")));for(var entry:files.entrySet())require(NextflowFiles.fingerprint(entry.getValue(),33554432).equals(NextflowFiles.pin(destination.resolve(NextflowFiles.member(entry.getKey())),33554432,()->{})),"Captured original/worker source changed: "+entry.getKey());for(String name:List.of("profiles.json","worker-profile.json"))require(Arrays.equals(resource(name),NextflowFiles.bytes(destination.resolve(name),4194304)),"Captured exact source/worker profile changed");
    }
    static Map<String,Object> execute(Path home,LeafCutterWorkflowRequest.Request request,Prepared runtime,Map<String,Object> effective)throws Exception {
        Files.createDirectory(home);Files.write(home.resolve("runtime.original.json"),runtime.original(),StandardOpenOption.CREATE_NEW);NextflowFiles.writeJson(home.resolve("request.json"),effective);for(String name:List.of("worker.py","supervisor.py"))Files.write(home.resolve(name),resource(name),StandardOpenOption.CREATE_NEW);
        var command=List.of(runtime.python().toString(),"-I","-B",home.resolve("supervisor.py").toString(),"--runtime",home.resolve("runtime.original.json").toString(),"--out",home.toString(),"--worker",home.resolve("worker.py").toString(),"--request",home.resolve("request.json").toString(),"--timeout",Integer.toString(request.timeout()),"--maximum-output-bytes",Long.toString(request.outputBytes()),"--maximum-files",Integer.toString(request.maximumFiles()));var builder=new ProcessBuilder(command).directory(home.toFile()).redirectOutput(home.resolve("supervisor.stdout").toFile()).redirectError(home.resolve("supervisor.stderr").toFile());builder.environment().keySet().removeIf(k->k.startsWith("PYTHON")||k.startsWith("R_")||k.startsWith("OMICS_LEAFCUTTER_")||Set.of("JAVA_TOOL_OPTIONS","_JAVA_OPTIONS","JDK_JAVA_OPTIONS").contains(k));var guard=new Guard(home);Thread hook=new Thread(guard::stop,"leafcutter-owned-cleanup");Runtime.getRuntime().addShutdownHook(hook);int code=-1;Exception error=null;long started=System.nanoTime();
        try{
            Process process=guard.start(builder);process.getOutputStream().close();while(!process.waitFor(100,TimeUnit.MILLISECONDS)){guard.observe();require(System.nanoTime()-started<TimeUnit.SECONDS.toNanos((long)request.timeout()+30),"Owned original workflow supervisor exceeded timeout/cleanup grace");}guard.observe();code=process.exitValue();require(code==0,"Original LeafCutter batch failed; all earlier cases remain provisional. Read worker/original-error.traceback, original.process.json and case stdout/stderr");var report=read(home.resolve("COMPLETED.json"),67108864);var receipt=read(home.resolve("original.process.json"),16777216);require(text(report.get("status")).equals("PASS_COMPLETE_ORIGINAL_LEAFCUTTER_WORKFLOWS_ONLY")&&Boolean.FALSE.equals(report.get("namespace_patched"))&&Boolean.FALSE.equals(report.get("analysis_installed_software"))&&list(report.get("cases")).size()==request.analyses().size()&&integer(receipt.get("exit_code"),0,0)==0&&list(receipt.get("owned_live_after_cleanup")).isEmpty(),"Complete original workflow/cleanup family not admitted");return report;
        }catch(Exception failure){error=failure;throw failure;}finally{
            boolean interrupted=Thread.interrupted();guard.stop();var receipt=new LinkedHashMap<String,Object>();receipt.put("command",command);receipt.put("exit_code",code);receipt.put("elapsed_millis",TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-started));receipt.put("owned_processes",guard.receipts());receipt.put("owned_live_after_cleanup",guard.live());receipt.put("status",error==null&&guard.live().isEmpty()?"completed-process-only":"FAIL2_NO_RESULT_ADMITTED");if(error!=null)receipt.put("error",error.toString());try{NextflowFiles.writeJson(home.resolve("java-process.json"),receipt);}finally{try{Runtime.getRuntime().removeShutdownHook(hook);}catch(IllegalStateException ignored){/* Shutdown owns cleanup. */}if(interrupted)Thread.currentThread().interrupt();}require(guard.live().isEmpty(),"Owned workflow processes remain alive; no result admitted");
        }
    }
    private static final class Guard {
        final Path home;Process root;boolean stopped;final Map<Long,ProcessHandle> handles=new LinkedHashMap<>();final Map<Long,String> starts=new LinkedHashMap<>();
        Guard(Path home){this.home=home;}
        synchronized Process start(ProcessBuilder builder)throws IOException{require(!stopped,"Owned guard already stopped");root=builder.start();observe();return root;}
        synchronized void observe(){if(root!=null){remember(root.toHandle());for(var handle:new ArrayList<>(handles.values()))handle.descendants().forEach(this::remember);}}
        void remember(ProcessHandle handle){handles.putIfAbsent(handle.pid(),handle);starts.putIfAbsent(handle.pid(),handle.info().startInstant().map(Instant::toString).orElse("unavailable"));}
        synchronized List<Long> live(){observe();return handles.values().stream().filter(ProcessHandle::isAlive).map(ProcessHandle::pid).toList();}
        synchronized List<Map<String,Object>> receipts(){return handles.values().stream().map(h->Map.<String,Object>of("pid",h.pid(),"start_instant",starts.get(h.pid()),"alive",h.isAlive())).toList();}
        synchronized void stop(){if(stopped)return;stopped=true;observe();if(root==null)return;try{if(root.isAlive()){try{Files.writeString(home.resolve("CANCEL_REQUESTED"),Instant.now()+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);}catch(IOException ignored){/* Sampled handles remain the fallback. */}root.waitFor(8,TimeUnit.SECONDS);}}catch(InterruptedException interrupted){Thread.currentThread().interrupt();}for(var h:new ArrayList<>(handles.values()))if(h.isAlive())h.destroy();long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(3);while(!live().isEmpty()&&System.nanoTime()<end){try{Thread.sleep(25);}catch(InterruptedException interrupted){Thread.currentThread().interrupt();break;}}for(var h:new ArrayList<>(handles.values()))if(h.isAlive())h.destroyForcibly();end=System.nanoTime()+TimeUnit.SECONDS.toNanos(3);while(!live().isEmpty()&&System.nanoTime()<end){try{Thread.sleep(25);}catch(InterruptedException interrupted){Thread.currentThread().interrupt();break;}}}
    }
}
